#include <stdlib.h>
#include <string.h>
#include <immintrin.h>
#include <omp.h>

#if defined(__AVX512F__)
#define MR 12
#define NR 32
#define KC 192
#else
#define MR 6
#define NR 16
#define KC 256
#endif

#define MC (MR * 8)
#define NC (NR * 8)

#if defined(__AVX512F__)

#define DECL(r) __m512 c##r##0 = _mm512_setzero_ps(), c##r##1 = _mm512_setzero_ps();
#define ROW(r) { __m512 av = _mm512_set1_ps(a[r]); \
    c##r##0 = _mm512_fmadd_ps(av, b0, c##r##0); \
    c##r##1 = _mm512_fmadd_ps(av, b1, c##r##1); }
#define ST(r) { float *cr = c + (size_t)(r) * ldc; \
    _mm512_storeu_ps(cr, c##r##0); _mm512_storeu_ps(cr + 16, c##r##1); }
#define AD(r) { float *cr = c + (size_t)(r) * ldc; \
    _mm512_storeu_ps(cr, _mm512_add_ps(_mm512_loadu_ps(cr), c##r##0)); \
    _mm512_storeu_ps(cr + 16, _mm512_add_ps(_mm512_loadu_ps(cr + 16), c##r##1)); }
#define PF(r) { __builtin_prefetch(c + (size_t)(r) * ldc, 1, 3); \
    __builtin_prefetch(c + (size_t)(r) * ldc + 16, 1, 3); }

static void kern(int kc, const float *restrict a, const float *restrict b,
                 float *restrict c, size_t ldc, int first)
{
    DECL(0) DECL(1) DECL(2) DECL(3) DECL(4) DECL(5)
    DECL(6) DECL(7) DECL(8) DECL(9) DECL(10) DECL(11)
    PF(0) PF(1) PF(2) PF(3) PF(4) PF(5)
    PF(6) PF(7) PF(8) PF(9) PF(10) PF(11)

    for (int k = 0; k < kc; k++) {
        __m512 b0 = _mm512_load_ps(b);
        __m512 b1 = _mm512_load_ps(b + 16);
        __builtin_prefetch(b + 8 * NR, 0, 3);
        ROW(0) ROW(1) ROW(2) ROW(3) ROW(4) ROW(5)
        ROW(6) ROW(7) ROW(8) ROW(9) ROW(10) ROW(11)
        a += MR;
        b += NR;
    }

    if (first) {
        ST(0) ST(1) ST(2) ST(3) ST(4) ST(5)
        ST(6) ST(7) ST(8) ST(9) ST(10) ST(11)
    } else {
        AD(0) AD(1) AD(2) AD(3) AD(4) AD(5)
        AD(6) AD(7) AD(8) AD(9) AD(10) AD(11)
    }
}

#else

#define DECL(r) __m256 c##r##0 = _mm256_setzero_ps(), c##r##1 = _mm256_setzero_ps();
#define ROW(r) { __m256 av = _mm256_broadcast_ss(a + (r)); \
    c##r##0 = _mm256_fmadd_ps(av, b0, c##r##0); \
    c##r##1 = _mm256_fmadd_ps(av, b1, c##r##1); }
#define ST(r) { float *cr = c + (size_t)(r) * ldc; \
    _mm256_storeu_ps(cr, c##r##0); _mm256_storeu_ps(cr + 8, c##r##1); }
#define AD(r) { float *cr = c + (size_t)(r) * ldc; \
    _mm256_storeu_ps(cr, _mm256_add_ps(_mm256_loadu_ps(cr), c##r##0)); \
    _mm256_storeu_ps(cr + 8, _mm256_add_ps(_mm256_loadu_ps(cr + 8), c##r##1)); }
#define PF(r) { __builtin_prefetch(c + (size_t)(r) * ldc, 1, 3); }

static void kern(int kc, const float *restrict a, const float *restrict b,
                 float *restrict c, size_t ldc, int first)
{
    DECL(0) DECL(1) DECL(2) DECL(3) DECL(4) DECL(5)
    PF(0) PF(1) PF(2) PF(3) PF(4) PF(5)

    for (int k = 0; k < kc; k++) {
        __m256 b0 = _mm256_load_ps(b);
        __m256 b1 = _mm256_load_ps(b + 8);
        ROW(0) ROW(1) ROW(2) ROW(3) ROW(4) ROW(5)
        a += MR;
        b += NR;
    }

    if (first) {
        ST(0) ST(1) ST(2) ST(3) ST(4) ST(5)
    } else {
        AD(0) AD(1) AD(2) AD(3) AD(4) AD(5)
    }
}

#endif

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;

    int nstrips = (n + MR - 1) / MR;
    int npanels = (n + NR - 1) / NR;

    size_t asz = ((size_t)nstrips * MR * n * sizeof(float) + 63) & ~(size_t)63;
    size_t bsz = ((size_t)npanels * NR * n * sizeof(float) + 63) & ~(size_t)63;
    float *Ap = (float *)aligned_alloc(64, asz);
    float *Bp = (float *)aligned_alloc(64, bsz);

    int nk = (n + KC - 1) / KC;
    int kcb = (n + nk - 1) / nk;

    int mblocks = (n + MC - 1) / MC;
    int nblocks = (n + NC - 1) / NC;
    int ntasks = mblocks * nblocks;

    #pragma omp parallel
    {
        /* B panel p: columns [p*NR, p*NR+NR), k-major, zero padded. */
        #pragma omp for schedule(static) nowait
        for (int p = 0; p < npanels; p++) {
            float *dst = Bp + (size_t)p * n * NR;
            int j0 = p * NR;
            int w = n - j0 < NR ? n - j0 : NR;
            for (int k = 0; k < n; k++) {
                const float *src = B + (size_t)k * n + j0;
                float *d = dst + (size_t)k * NR;
                if (w == NR) {
                    memcpy(d, src, NR * sizeof(float));
                } else {
                    int j = 0;
                    for (; j < w; j++) d[j] = src[j];
                    for (; j < NR; j++) d[j] = 0.0f;
                }
            }
        }

        /* A strip s: rows [s*MR, s*MR+MR), k-major, contiguous writes. */
        #pragma omp for schedule(static)
        for (int s = 0; s < nstrips; s++) {
            float *dst = Ap + (size_t)s * n * MR;
            int i0 = s * MR;
            int h = n - i0 < MR ? n - i0 : MR;
            if (h == MR) {
                const float *rows[MR];
                for (int r = 0; r < MR; r++) rows[r] = A + (size_t)(i0 + r) * n;
                for (int k = 0; k < n; k++) {
                    float *d = dst + (size_t)k * MR;
                    #pragma GCC unroll 12
                    for (int r = 0; r < MR; r++) d[r] = rows[r][k];
                }
            } else {
                for (int k = 0; k < n; k++) {
                    float *d = dst + (size_t)k * MR;
                    for (int r = 0; r < MR; r++)
                        d[r] = r < h ? A[(size_t)(i0 + r) * n + k] : 0.0f;
                }
            }
        }

        #pragma omp for schedule(dynamic, 1)
        for (int t = 0; t < ntasks; t++) {
            int ib = t / nblocks, jb = t % nblocks;
            int i0 = ib * MC;
            int iend = i0 + MC < n ? i0 + MC : n;
            int jstart = jb * NC;
            int jend = jstart + NC < n ? jstart + NC : n;

            for (int k0 = 0; k0 < n; k0 += kcb) {
                int kc = n - k0 < kcb ? n - k0 : kcb;
                int first = (k0 == 0);
                for (int j = jstart; j < jend; j += NR) {
                    const float *bp = Bp + (size_t)(j / NR) * n * NR + (size_t)k0 * NR;
                    int nr = n - j < NR ? n - j : NR;
                    for (int i = i0; i < iend; i += MR) {
                        const float *ap = Ap + (size_t)(i / MR) * n * MR + (size_t)k0 * MR;
                        int mr = n - i < MR ? n - i : MR;
                        float *cp = C + (size_t)i * n + j;
                        if (mr == MR && nr == NR) {
                            kern(kc, ap, bp, cp, (size_t)n, first);
                        } else {
                            float tmp[MR * NR] __attribute__((aligned(64)));
                            kern(kc, ap, bp, tmp, NR, 1);
                            for (int r = 0; r < mr; r++) {
                                float *cr = cp + (size_t)r * n;
                                const float *tr = tmp + r * NR;
                                if (first)
                                    for (int jj = 0; jj < nr; jj++) cr[jj] = tr[jj];
                                else
                                    for (int jj = 0; jj < nr; jj++) cr[jj] += tr[jj];
                            }
                        }
                    }
                }
            }
        }
    }

    free(Ap);
    free(Bp);
}
